import{n as e,r as t,t as n}from"./banhmi-GqHpeFWA.js";import{n as r,r as i,t as a}from"./cat-sSHJabs0.js";var o=`#0087a8`,s=`#5c2483`,c=`#c25e12`,l=`#4a8b23`,u=(e,t)=>`\\dfrac{${e}}{${t}}`,d=[{layout:`hero`,color:c,icon:`Combine`,brand:`Year 7 Mathematics`,brandFr:`Maths 7e année`,brandHe:`מתמטיקה · Year 7`,eyebrow:`Unit 7 · 7.2 · Lesson 1`,eyebrowFr:`Unité 7 · 7.2 · Leçon 1`,eyebrowHe:`יחידה 7 · 7.2 · שיעור 1`,title:`Adding Fractions`,titleFr:`Additionner des fractions`,titleHe:`חיבור שברים`,compact:!0,objective:`Add fractions with the same denominator, finish the answer, and add fractions with different denominators.`,objectiveFr:`Additionner des fractions de même dénominateur, terminer la réponse, et additionner des fractions de dénominateurs différents.`,objectiveHe:`לחבר שברים עם אותו מכנה, לסיים את התשובה, ולחבר שברים עם מכנים שונים.`,card:{icon:`Lightbulb`,badge:`The big idea`,badgeFr:`L’idée clé`,badgeHe:`הרעיון המרכזי`,text:`You can only add pieces of the **same size**. If they are different, **cut them** to the same size first.`,textFr:`On additionne seulement des parts de **même taille**. Si elles sont différentes, **coupe-les** d’abord à la même taille.`,textHe:`אפשר לחבר רק חתיכות **באותו גודל**. אם הן שונות, קודם **חותכים אותן** לאותו גודל.`}},{layout:`split`,accent:c,icon:`Circle`,eyebrow:`Think first`,eyebrowFr:`Réfléchis d’abord`,eyebrowHe:`קודם חושבים`,title:`Lunch and Dinner`,titleFr:`Déjeuner et dîner`,titleHe:`צהריים וערב`,ratio:50,inlineSvg:t.STARTER,content:`Mr Bowen eats $${u(3,8)}$ of a pizza for lunch and $${u(2,8)}$ for dinner.`,contentFr:`M. Bowen mange $${u(3,8)}$ d’une pizza au déjeuner et $${u(2,8)}$ au dîner.`,contentHe:`מר בואן אוכל $${u(3,8)}$ פיצה בצהריים ו-$${u(2,8)}$ בערב.`,check:{id:`chk_lunch`,q:`How much of the pizza did he eat?`,qFr:`Quelle part de la pizza a-t-il mangée ?`,qHe:`כמה מהפיצה הוא אכל?`,options:[{val:`A`,text:`$${u(5,16)}$`},{val:`B`,text:`$${u(5,8)}$`},{val:`C`,text:`$${u(6,16)}$`}],correct:`B`,expEn:`3 eighths + 2 eighths = **5 eighths**. The pieces stay eighths. A adds the bottoms too, and $\\dfrac{5}{16}$ is **less** than his lunch on its own.`,expFr:`3 huitièmes + 2 huitièmes = **5 huitièmes**. Les parts restent des huitièmes. A additionne aussi les bas, et $\\dfrac{5}{16}$, c’est **moins** que son déjeuner tout seul.`,expHe:`3 שמיניות + 2 שמיניות = **5 שמיניות**. החתיכות נשארות שמיניות. A מחבר גם את המכנים, ו-$\\dfrac{5}{16}$ זה **פחות** מארוחת הצהריים לבד.`}},{layout:`split`,accent:o,icon:`Combine`,eyebrow:`The same denominator`,eyebrowFr:`Le même dénominateur`,eyebrowHe:`אותו מכנה`,title:`Eighths Is a Name`,titleFr:`« Huitièmes » est un nom`,titleHe:`"שמיניות" זה שם`,ratio:45,inlineSvg:t.APPLES,content:`The **numerator** counts. The **denominator** names the piece, like **apples**.`,contentFr:`Le **numérateur** compte. Le **dénominateur** donne le nom de la part, comme **pommes**.`,contentHe:`**המונה** סופר. **המכנה** נותן שם לחתיכה, כמו **תפוחים**.`,notes:[{tone:`write`,text:`**Same denominator:** add the numerators. The denominator stays the same.
$\\dfrac{3}{8} + \\dfrac{2}{8} = \\dfrac{5}{8}$`,textFr:`**Même dénominateur (same denominator) :** additionne les numérateurs. Le dénominateur ne change pas.
$\\dfrac{3}{8} + \\dfrac{2}{8} = \\dfrac{5}{8}$`,textHe:`**אותו מכנה (same denominator):** מחברים את המונים. המכנה נשאר אותו דבר.
$\\dfrac{3}{8} + \\dfrac{2}{8} = \\dfrac{5}{8}$`},{tone:`homework`,text:`Never add the denominators: the pieces do not get smaller.`,textFr:`N’additionne jamais les dénominateurs : les parts ne deviennent pas plus petites.`,textHe:`אף פעם לא מחברים את המכנים: החתיכות לא נעשות קטנות יותר.`}]},{layout:`split`,accent:o,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Add and Say It`,titleFr:`Additionne et dis-le`,titleHe:`חברו ואמרו`,ratio:45,content:`Type each top. Then **say** each answer in English: **four fifths**.`,contentFr:`Écris chaque haut. Puis **dis** chaque réponse en anglais : **four fifths**.`,contentHe:`כתבו כל מונה. אחר כך **אמרו** כל תשובה באנגלית: **four fifths**.`,activity:{id:`act_same`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`1/5 + 3/5 = [4]/5`,`4/9 + 4/9 = [8]/9`,`3/10 + 6/10 = [9]/10`,`3/11 + 2/11 + 5/11 = [10]/11`],split:2,explain:`**a** four fifths, **b** eight ninths, **c** nine tenths, **d** ten elevenths. Three fractions add the same way: 3 + 2 + 5 = 10.`,explainFr:`**a** four fifths (quatre cinquièmes), **b** eight ninths, **c** nine tenths, **d** ten elevenths. Trois fractions s’additionnent pareil : 3 + 2 + 5 = 10.`,explainHe:`**a** four fifths (ארבע חמישיות), **b** eight ninths, **c** nine tenths, **d** ten elevenths. שלושה שברים מחברים באותה דרך: $3 + 2 + 5 = 10$.`}},{layout:`split`,accent:s,icon:`Scissors`,eyebrow:`Finish it`,eyebrowFr:`Termine`,eyebrowHe:`מסיימים`,title:`The Smallest Numbers`,titleFr:`Les plus petits nombres`,titleHe:`המספרים הקטנים ביותר`,ratio:45,content:`$${u(7,12)} + ${u(1,12)} = ${u(8,12)}$`,contentFr:`$${u(7,12)} + ${u(1,12)} = ${u(8,12)}$`,contentHe:`$${u(7,12)} + ${u(1,12)} = ${u(8,12)}$`,check:{id:`chk_smallest`,q:`Which is $${u(8,12)}$ with the smallest numbers?`,qFr:`Quelle est $${u(8,12)}$ avec les plus petits nombres ?`,qHe:`מהו $${u(8,12)}$ עם המספרים הקטנים ביותר?`,options:[{val:`A`,text:`$${u(4,6)}$`},{val:`B`,text:`$${u(2,3)}$`},{val:`C`,text:`$${u(7,11)}$`}],correct:`B`,expEn:`A is the same amount, but **not finished**: 4 and 6 can still be divided by 2. The biggest number that divides 8 and 12 is **4**: $\\dfrac{8}{12} = \\dfrac{2}{3}$ in one step. C takes 1 away from both, which changes the amount.`,expFr:`A, c’est la même quantité, mais **pas terminée** : 4 et 6 se divisent encore par 2. Le plus grand nombre qui divise 8 et 12, c’est **4** : $\\dfrac{8}{12} = \\dfrac{2}{3}$ en une étape. C enlève 1 aux deux, ce qui change la quantité.`,expHe:`A זו אותה כמות, אבל **לא גמורה**: אפשר עוד לחלק את 4 ואת 6 ב-2. המספר הגדול ביותר שמחלק את 8 ואת 12 הוא **4**: $\\dfrac{8}{12} = \\dfrac{2}{3}$ בצעד אחד. C מוריד 1 משניהם, וזה משנה את הכמות.`}},{layout:`split`,accent:s,icon:`Scissors`,eyebrow:`Key words`,eyebrowFr:`Mots clés`,eyebrowHe:`מילות מפתח`,title:`Divide by the HCF`,titleFr:`Divise par le PGCD`,titleHe:`מחלקים בממג"ב`,ratio:50,inlineSvg:t.SIMPLEST,content:`All three are the same amount. Only $\\dfrac{2}{3}$ is finished.`,contentFr:`Les trois sont la même quantité. Seule $\\dfrac{2}{3}$ est terminée.`,contentHe:`שלושתם אותה כמות. רק $\\dfrac{2}{3}$ גמור.`,notes:[{tone:`write`,text:`**Simplest form:** divide the numerator and the denominator by their **HCF**.
$\\dfrac{8 \\div 4}{12 \\div 4} = \\dfrac{2}{3}$`,textFr:`**Forme la plus simple (simplest form) :** divise le numérateur et le dénominateur par leur **PGCD**.
$\\dfrac{8 \\div 4}{12 \\div 4} = \\dfrac{2}{3}$`,textHe:`**הצורה המצומצמת (simplest form):** מחלקים את המונה ואת המכנה **בממג"ב** שלהם (HCF).
$\\dfrac{8 \\div 4}{12 \\div 4} = \\dfrac{2}{3}$`}]},{layout:`split`,accent:s,icon:`Circle`,eyebrow:`Finish it`,eyebrowFr:`Termine`,eyebrowHe:`מסיימים`,title:`Six Fifths`,titleFr:`Six cinquièmes`,titleHe:`שש חמישיות`,ratio:50,inlineSvg:t.SIX_FIFTHS,content:`$${u(3,5)} + ${u(3,5)} = ${u(6,5)}$. One pizza has only **5** fifths, so the sixth slice starts a new pizza.`,contentFr:`$${u(3,5)} + ${u(3,5)} = ${u(6,5)}$. Une pizza n’a que **5** cinquièmes : la sixième part commence une nouvelle pizza.`,contentHe:`$${u(3,5)} + ${u(3,5)} = ${u(6,5)}$. בפיצה אחת יש רק **5** חמישיות, אז החתיכה השישית מתחילה פיצה חדשה.`,notes:[{tone:`tip`,badge:`From 7.1`,badgeFr:`Vu en 7.1`,badgeHe:`מ-7.1`,text:`**Improper → mixed:** divide. $6 \\div 5 = 1$ remainder $1$, so $\\dfrac{6}{5} = 1\\dfrac{1}{5}$`,textFr:`**Impropre → mixte :** divise. $6 \\div 5 = 1$ reste $1$, donc $\\dfrac{6}{5} = 1\\dfrac{1}{5}$`,textHe:`**מדומה ← מעורב:** מחלקים. $6 \\div 5 = 1$ שארית $1$, ולכן $\\dfrac{6}{5} = 1\\dfrac{1}{5}$`}]},{layout:`split`,accent:s,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Finish Them`,titleFr:`Termine-les`,titleHe:`סיימו אותם`,ratio:40,content:`Add. Then write each answer in its **simplest form**, or as a **mixed number**.`,contentFr:`Additionne. Puis écris chaque réponse sous sa **forme la plus simple**, ou en **nombre mixte**.`,contentHe:`חברו. אחר כך כתבו כל תשובה **בצורה המצומצמת**, או **כמספר מעורב**.`,notes:[{tone:`tip`,badge:!1,text:`**d** needs both: a mixed number, then the simplest form.`,textFr:`**d** demande les deux : un nombre mixte, puis la forme la plus simple.`,textHe:`ב-**d** צריך את שניהם: מספר מעורב, ואז הצורה המצומצמת.`}],activity:{id:`act_finish`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`1/6 + 1/6 = [2]/6 = [1]/[3]`,`5/12 + 5/12 = [10]/12 = [5]/[6]`,`7/9 + 4/9 = [11]/9 = [1] [2]/9`,{q:`7/12 + 11/12 = [18]/12 = [1] [1]/[2]`,hint:`18 ÷ 12 = 1 remainder 6, so 1 6/12. Then divide 6 and 12 by 6.`,hintFr:`18 ÷ 12 = 1 reste 6, donc 1 6/12. Puis divise 6 et 12 par 6.`,hintHe:`18 ÷ 12 = 1 שארית 6, כלומר 1 6/12. אחר כך חלקו את 6 ואת 12 ב-6.`}],split:4,explain:`**a** ÷ 2, **b** ÷ 2. **c** $11 \\div 9 = 1$ remainder 2. **d** $\\dfrac{18}{12} = 1\\dfrac{6}{12} = 1\\dfrac{1}{2}$: the whole number stays, the fraction ÷ 6.`,explainFr:`**a** ÷ 2, **b** ÷ 2. **c** $11 \\div 9 = 1$ reste 2. **d** $\\dfrac{18}{12} = 1\\dfrac{6}{12} = 1\\dfrac{1}{2}$ : le nombre entier reste, la fraction ÷ 6.`,explainHe:`**a** $\\div 2$ ו-**b** $\\div 2$. **c** $11 \\div 9 = 1$ שארית 2. **d** $\\dfrac{18}{12} = 1\\dfrac{6}{12} = 1\\dfrac{1}{2}$: המספר השלם נשאר, והשבר $\\div 6$.`}},{layout:`split`,accent:c,icon:`Circle`,eyebrow:`Think first`,eyebrowFr:`Réfléchis d’abord`,eyebrowHe:`קודם חושבים`,title:`Mr Bowen’s Pizza Test`,titleFr:`Le test pizza de M. Bowen`,titleHe:`מבחן הפיצה של מר בואן`,ratio:50,inlineSvg:t.PIZZA_TEST,content:`Mr Bowen tests two pizza shops for his party. **Shop A** cuts its pizza into **4**. **Shop B** cuts into **8**. He eats one slice from each.`,contentFr:`M. Bowen teste deux pizzerias pour sa fête. La **pizzeria A** coupe sa pizza en **4**. La **pizzeria B** en **8**. Il mange une part de chaque.`,contentHe:`מר בואן בודק שתי פיצריות למסיבה שלו. **פיצרייה A** חותכת את הפיצה ל-**4**. **פיצרייה B** חותכת ל-**8**. הוא אוכל חתיכה אחת מכל אחת.`,check:{id:`chk_pizza_test`,q:`How much pizza did he eat? $${u(1,4)} + ${u(1,8)} = \\;?$`,qFr:`Combien de pizza a-t-il mangé ? $${u(1,4)} + ${u(1,8)} = \\;?$`,qHe:`כמה פיצה הוא אכל? $${u(1,4)} + ${u(1,8)} = \\;?$`,options:[{val:`A`,text:`$${u(2,12)}$`},{val:`B`,text:`$${u(3,8)}$`},{val:`C`,text:`$${u(2,8)}$`}],correct:`B`,expEn:`Cut Shop A’s big slice in two: $\\dfrac{1}{4} = \\dfrac{2}{8}$. Now both are eighths: $\\dfrac{2}{8} + \\dfrac{1}{8} = \\dfrac{3}{8}$. A adds the tops and the bottoms: $\\dfrac{2}{12}$ is less than the quarter slice on its own.`,expFr:`Coupe la grande part de la pizzeria A en deux : $\\dfrac{1}{4} = \\dfrac{2}{8}$. Maintenant, ce sont deux fois des huitièmes : $\\dfrac{2}{8} + \\dfrac{1}{8} = \\dfrac{3}{8}$. A additionne les hauts et les bas : $\\dfrac{2}{12}$, c’est moins que le quart tout seul.`,expHe:`חותכים את החתיכה הגדולה של פיצרייה A לשתיים: $\\dfrac{1}{4} = \\dfrac{2}{8}$. עכשיו שתיהן שמיניות: $\\dfrac{2}{8} + \\dfrac{1}{8} = \\dfrac{3}{8}$. A מחבר את המונים ואת המכנים: $\\dfrac{2}{12}$ זה פחות מחתיכת הרבע לבד.`}},{layout:`split`,accent:c,icon:`Scissors`,eyebrow:`Key words`,eyebrowFr:`Mots clés`,eyebrowHe:`מילות מפתח`,title:`Common Denominator`,titleFr:`Dénominateur commun`,titleHe:`מכנה משותף`,ratio:50,inlineSvg:t.QUARTER_EIGHTH,content:`Cut the big slice first. Then add.`,contentFr:`Coupe d’abord la grande part. Puis additionne.`,contentHe:`קודם חותכים את החתיכה הגדולה. אחר כך מחברים.`,notes:[{tone:`write`,text:`**Common denominator:** the same denominator for both fractions. It is in **both** times tables.`,textFr:`**Dénominateur commun (common denominator) :** le même dénominateur pour les deux fractions. Il est dans les **deux** tables de multiplication.`,textHe:`**מכנה משותף (common denominator):** אותו מכנה לשני השברים. הוא נמצא **בשני** לוחות הכפל.`},{tone:`tip`,badge:`From 7.1`,badgeFr:`Vu en 7.1`,badgeHe:`מ-7.1`,text:`Change a fraction with **equivalent fractions**: multiply the top and the bottom by the same number.`,textFr:`Transforme une fraction avec les **fractions équivalentes** : multiplie le haut et le bas par le même nombre.`,textHe:`משנים שבר בעזרת **שברים שקולים**: כופלים את המונה ואת המכנה באותו מספר.`}]},{layout:`split`,accent:c,icon:`Scissors`,eyebrow:`Think first`,eyebrowFr:`Réfléchis d’abord`,eyebrowHe:`קודם חושבים`,title:`Thirds and Quarters`,titleFr:`Tiers et quarts`,titleHe:`שלישים ורבעים`,ratio:50,inlineSvg:t.THIRDS_QUARTERS,content:`Mr Bowen wants to add **a third** and **a quarter**. Neither one is a multiple of the other.`,contentFr:`M. Bowen veut additionner **un tiers** et **un quart**. Aucun n’est un multiple de l’autre.`,contentHe:`מר בואן רוצה לחבר **שליש** ו**רבע**. אף אחד מהם לא כפולה של השני.`,check:{id:`chk_thirds_quarters`,q:`What size pieces can he cut **both** into?`,qFr:`En quelles parts peut-il couper les **deux** ?`,qHe:`לאיזה גודל חתיכות אפשר לחתוך את **שניהם**?`,options:[{val:`A`,text:`sevenths`,textFr:`des septièmes`,textHe:`שביעיות`},{val:`B`,text:`twelfths`,textFr:`des douzièmes`,textHe:`שנים-עשר חלקים`},{val:`C`,text:`quarters`,textFr:`des quarts`,textHe:`רבעים`}],correct:`B`,expEn:`**12** is in the 3 times table and the 4 times table. Cut each third into 4 and each quarter into 3: both are twelfths. 7 is 3 + 4, and it is in neither times table.`,expFr:`**12** est dans la table de 3 et dans la table de 4. Coupe chaque tiers en 4 et chaque quart en 3 : ce sont des douzièmes. 7, c’est 3 + 4, et il n’est dans aucune des deux tables.`,expHe:`**12** נמצא בלוח הכפל של 3 ובלוח הכפל של 4. חותכים כל שליש ל-4 וכל רבע ל-3: שניהם חלקים של 12. 7 זה $3 + 4$, והוא לא נמצא באף אחד מלוחות הכפל.`}},{layout:`split`,accent:c,icon:`Search`,eyebrow:`Find the bottom`,eyebrowFr:`Trouve le bas`,eyebrowHe:`מוצאים את המכנה`,title:`Where the Tables Meet`,titleFr:`Là où les tables se rencontrent`,titleHe:`איפה לוחות הכפל נפגשים`,ratio:45,content:`Add $${u(3,4)} + ${u(1,6)}$.\n\n**4** times table: 4, 8, 12, 16, 20, 24\n**6** times table: 6, 12, 18, 24`,contentFr:`Additionne $${u(3,4)} + ${u(1,6)}$.\n\nTable de **4** : 4, 8, 12, 16, 20, 24\nTable de **6** : 6, 12, 18, 24`,contentHe:`חברו $${u(3,4)} + ${u(1,6)}$.\n\nלוח הכפל של **4**: $4, 8, 12, 16, 20, 24$\nלוח הכפל של **6**: $6, 12, 18, 24$`,check:{id:`chk_lcm`,q:`Which common denominator keeps the numbers smallest?`,qFr:`Quel dénominateur commun garde les plus petits nombres ?`,qHe:`איזה מכנה משותף שומר על המספרים הכי קטנים?`,options:[{val:`A`,text:`24 (4 × 6)`},{val:`B`,text:`12`},{val:`C`,text:`10 (4 + 6)`}],correct:`B`,expEn:`**12** is the first number in both times tables: the **lowest common multiple** (LCM). $\\dfrac{9}{12} + \\dfrac{2}{12} = \\dfrac{11}{12}$. 24 works too, but the numbers are bigger and you must simplify at the end. 10 is not in either times table.`,expFr:`**12** est le premier nombre dans les deux tables : le **plus petit commun multiple** (PPCM). $\\dfrac{9}{12} + \\dfrac{2}{12} = \\dfrac{11}{12}$. 24 marche aussi, mais les nombres sont plus grands et il faut simplifier à la fin. 10 n’est dans aucune des deux tables.`,expHe:`**12** הוא המספר הראשון בשני לוחות הכפל: **הכפולה המשותפת הקטנה ביותר** (כמק"ב, LCM). $\\dfrac{9}{12} + \\dfrac{2}{12} = \\dfrac{11}{12}$. גם 24 עובד, אבל המספרים גדולים יותר וצריך לצמצם בסוף. 10 לא נמצא באף אחד מלוחות הכפל.`}},{layout:`split`,accent:c,icon:`Scissors`,eyebrow:`Different denominators`,eyebrowFr:`Dénominateurs différents`,eyebrowHe:`מכנים שונים`,title:`Adding With the LCM`,titleFr:`Additionner avec le PPCM`,titleHe:`מחברים בעזרת הכמק"ב`,ratio:50,inlineSvg:t.DIFF_METHOD,content:`Follow the arrows: the same × on the top and the bottom.`,contentFr:`Suis les flèches : le même × en haut et en bas.`,contentHe:`עקבו אחרי החצים: אותו כפל במונה ובמכנה.`,notes:[{tone:`write`,text:`**Different denominators:**
1 Find the **LCM** of the denominators.
2 Change both fractions to that denominator.
3 Add the numerators.`,textFr:`**Dénominateurs différents (different denominators) :**
1 Trouve le **PPCM** des dénominateurs.
2 Transforme les deux fractions avec ce dénominateur.
3 Additionne les numérateurs.`,textHe:`**מכנים שונים (different denominators):**
1 מוצאים את **הכמק"ב** (LCM) של המכנים.
2 מרחיבים את שני השברים למכנה הזה.
3 מחברים את המונים.`}]},{layout:`split`,accent:c,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Change, Then Add`,titleFr:`Transforme, puis additionne`,titleHe:`מרחיבים, ואז מחברים`,ratio:35,content:`**a** and **b**: change **one** fraction.
**c** and **d**: change **both**.`,contentFr:`**a** et **b** : transforme **une** fraction.
**c** et **d** : transforme les **deux**.`,contentHe:`**a** ו-**b**: מרחיבים שבר **אחד**.
**c** ו-**d**: מרחיבים את **שניהם**.`,activity:{id:`act_diff`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`1/3 + 2/9 = [3]/9 + 2/9 = [5]/9`,`1/5 + 3/10 = [2]/10 + 3/10 = [1]/[2]`,`2/3 + 1/4 = [8]/12 + [3]/12 = [11]/12`,{q:`3/4 + 5/6 = [9]/12 + [10]/12 = [1] [7]/12`,hint:`The LCM of 4 and 6 is 12. 4 × 3 = 12 and 6 × 2 = 12: do the same to each top.`,hintFr:`Le PPCM de 4 et 6 est 12. 4 × 3 = 12 et 6 × 2 = 12 : fais pareil à chaque haut.`,hintHe:`הכמק"ב של 4 ו-6 הוא 12. 4 × 3 = 12 ו-6 × 2 = 12: עשו אותו דבר לכל מונה.`}],split:4,explain:`**a** $1 \\times 3$, **b** $1 \\times 2$, then $\\dfrac{5}{10} = \\dfrac{1}{2}$. **c** $\\times 4$ and $\\times 3$. **d** $\\times 3$ and $\\times 2$, then $19 \\div 12 = 1$ remainder 7.`,explainFr:`**a** $1 \\times 3$, **b** $1 \\times 2$, puis $\\dfrac{5}{10} = \\dfrac{1}{2}$. **c** $\\times 4$ et $\\times 3$. **d** $\\times 3$ et $\\times 2$, puis $19 \\div 12 = 1$ reste 7.`,explainHe:`**a** $1 \\times 3$ ו-**b** $1 \\times 2$, ואז $\\dfrac{5}{10} = \\dfrac{1}{2}$. **c** $\\times 4$ ו-$\\times 3$. **d** $\\times 3$ ו-$\\times 2$, ואז $19 \\div 12 = 1$ שארית 7.`}},{layout:`split`,accent:l,icon:`Scale`,eyebrow:`More than 1?`,eyebrowFr:`Plus de 1 ?`,eyebrowHe:`יותר מ-1?`,title:`Arms Up or Arms Down`,titleFr:`Bras en haut ou en bas`,titleHe:`ידיים למעלה או למטה`,ratio:45,content:`In class: **arms up** if the sum is more than 1, **arms down** if it is less. Look before you work it out.`,contentFr:`En classe : **bras en haut** si la somme fait plus de 1, **bras en bas** si elle fait moins. Regarde avant de calculer.`,contentHe:`בכיתה: **ידיים למעלה** אם הסכום יותר מ-1, **ידיים למטה** אם פחות. הסתכלו לפני שאתם מחשבים.`,notes:[{tone:`tip`,badge:!1,text:`Both **more than a half**: more than 1. Both **less than a half**: less than 1.`,textFr:`Les deux **plus d’une demie** : plus de 1. Les deux **moins d’une demie** : moins de 1.`,textHe:`שניהם **יותר מחצי**: יותר מ-1. שניהם **פחות מחצי**: פחות מ-1.`}],check:{id:`chk_more_than_one`,q:`Which sum is **more than 1**?`,qFr:`Quelle somme fait **plus de 1** ?`,qHe:`איזה סכום הוא **יותר מ-1**?`,options:[{val:`A`,text:`$${u(2,5)} + ${u(3,10)}$`},{val:`B`,text:`$${u(5,9)} + ${u(5,9)}$`},{val:`C`,text:`$${u(5,11)} + ${u(4,11)}$`}],correct:`B`,expEn:`$\\dfrac{5}{9}$ is more than a half, so two of them make more than 1: $\\dfrac{10}{9} = 1\\dfrac{1}{9}$. In A and C both fractions are less than a half. Big numbers do not make a big fraction.`,expFr:`$\\dfrac{5}{9}$, c’est plus d’une demie, donc deux font plus de 1 : $\\dfrac{10}{9} = 1\\dfrac{1}{9}$. Dans A et C, les deux fractions font moins d’une demie. De grands nombres ne font pas une grande fraction.`,expHe:`$\\dfrac{5}{9}$ זה יותר מחצי, אז שניים כאלה הם יותר מ-1: $\\dfrac{10}{9} = 1\\dfrac{1}{9}$. ב-A וב-C שני השברים פחות מחצי. מספרים גדולים לא עושים שבר גדול.`}},{layout:`split`,accent:l,icon:`Coffee`,eyebrow:`Word problem`,eyebrowFr:`Problème`,eyebrowHe:`בעיה מילולית`,title:`Mr Bowen’s Coffee`,titleFr:`Le café de M. Bowen`,titleHe:`הקפה של מר בואן`,ratio:50,image:e,content:`Mr Bowen drinks $${u(3,10)}$ of a litre of cà phê sữa đá in the morning and $${u(1,2)}$ a litre after lunch. How much coffee is that?`,contentFr:`M. Bowen boit $${u(3,10)}$ de litre de cà phê sữa đá le matin et $${u(1,2)}$ litre après le déjeuner. Combien de café en tout ?`,contentHe:`מר בואן שותה $${u(3,10)}$ ליטר קפה קר וייטנאמי (cà phê sữa đá) בבוקר ו-$${u(1,2)}$ ליטר אחרי הצהריים. כמה קפה זה?`,activity:{id:`act_coffee`,type:`fill`,prompt:`Write it in its simplest form.`,promptFr:`Écris-la sous sa forme la plus simple.`,promptHe:`כתבו בצורה המצומצמת.`,lines:[`3/10 + 1/2 = 3/10 + [5]/10 = [8]/10 = [4]/[5]`],explain:`10 is in the 2 times table, so only the half changes: $\\dfrac{1}{2} = \\dfrac{5}{10}$. Then $\\dfrac{8}{10} = \\dfrac{4}{5}$ of a litre (÷ 2). He is very awake.`,explainFr:`10 est dans la table de 2, donc seule la demie change : $\\dfrac{1}{2} = \\dfrac{5}{10}$. Puis $\\dfrac{8}{10} = \\dfrac{4}{5}$ de litre (÷ 2). Il est très réveillé.`,explainHe:`10 נמצא בלוח הכפל של 2, אז רק החצי משתנה: $\\dfrac{1}{2} = \\dfrac{5}{10}$. ואז $\\dfrac{8}{10} = \\dfrac{4}{5}$ ליטר $(\\div 2)$. הוא ער מאוד.`}},{layout:`split`,accent:l,icon:`Route`,eyebrow:`Word problem`,eyebrowFr:`Problème`,eyebrowHe:`בעיה מילולית`,title:`One Bánh Mì`,titleFr:`Un seul bánh mì`,titleHe:`באן מי אחד`,ratio:50,image:n,content:`Mr Bowen rides across Hội An for **one** bánh mì. The ride there uses $${u(1,4)}$ of a tank of petrol. The ride home uses $${u(1,6)}$. How much petrol is that?`,contentFr:`M. Bowen traverse Hội An à moto pour **un seul** bánh mì. L’aller utilise $${u(1,4)}$ d’un réservoir d’essence. Le retour, $${u(1,6)}$. Combien d’essence en tout ?`,contentHe:`מר בואן נוסע על האופנוע לאורך כל הוי אן בשביל באן מי **אחד**. הנסיעה לשם צורכת $${u(1,4)}$ מיכל דלק. הנסיעה הביתה צורכת $${u(1,6)}$. כמה דלק זה?`,activity:{id:`act_banhmi`,type:`fill`,prompt:`Use the LCM of 4 and 6.`,promptFr:`Utilise le PPCM de 4 et 6.`,promptHe:`השתמשו בכמק"ב של 4 ו-6.`,lines:[`1/4 + 1/6 = [3]/12 + [2]/12 = [5]/12`],explain:`The LCM of 4 and 6 is 12: $\\times 3$ and $\\times 2$. $\\dfrac{5}{12}$ of a tank. The petrol cost more than the bánh mì.`,explainFr:`Le PPCM de 4 et 6 est 12 : $\\times 3$ et $\\times 2$. $\\dfrac{5}{12}$ du réservoir. L’essence a coûté plus cher que le bánh mì.`,explainHe:`הכמק"ב של 4 ו-6 הוא 12: $\\times 3$ ו-$\\times 2$. $\\dfrac{5}{12}$ מיכל. הדלק עלה יותר מהבאן מי.`}},{layout:`stack`,accent:o,icon:`ListChecks`,eyebrow:`Before you finish`,eyebrowFr:`Avant de finir`,eyebrowHe:`לפני שמסיימים`,title:`Can You Do These?`,titleFr:`Sais-tu faire ceci ?`,titleHe:`אתם יודעים לעשות את זה?`,items:[{text:`**Same denominator:** add the tops, keep the bottom.`,textFr:`**Même dénominateur :** additionne les hauts, garde le bas.`,textHe:`**אותו מכנה:** מחברים את המונים, המכנה נשאר.`},{text:`**Finish it:** the simplest form (÷ the HCF), or a mixed number when it is 1 or more.`,textFr:`**Termine :** la forme la plus simple (÷ le PGCD), ou un nombre mixte quand ça fait 1 ou plus.`,textHe:`**מסיימים:** הצורה המצומצמת (חילוק בממג"ב), או מספר מעורב כשזה 1 או יותר.`},{text:`**Different denominators:** the LCM, change both, then add the tops.`,textFr:`**Dénominateurs différents :** le PPCM, transforme les deux, puis additionne les hauts.`,textHe:`**מכנים שונים:** הכמק"ב, מרחיבים את שניהם, ואז מחברים את המונים.`}],notes:[{tone:`homework`,text:`The one trap: adding the **bottoms**. The pieces never get smaller when you add.`,textFr:`Le seul piège : additionner les **bas**. Les parts ne deviennent jamais plus petites quand on additionne.`,textHe:`המלכודת היחידה: לחבר את **המכנים**. החתיכות אף פעם לא נעשות קטנות יותר כשמחברים.`}]},{layout:`hero`,color:o,icon:`CheckCircle2`,title:`Lesson Complete!`,titleFr:`Leçon terminée !`,titleHe:`השיעור הסתיים!`,subtitle:`Now practise: **Same denominator**, then **Make them match**. Then Lesson 2, mixed numbers.`,subtitleFr:`Maintenant, entraîne-toi : **Même dénominateur**, puis **Même taille**. Ensuite la leçon 2, les nombres mixtes.`,subtitleHe:`עכשיו תרגלו: **אותו מכנה**, ואחר כך **מכנה משותף**. אחר כך שיעור 2, מספרים מעורבים.`}];function f(e){let t=e.flatMap(e=>[...e.notes||[],...(Array.isArray(e.columns)?e.columns:[]).flatMap(e=>e.notes||[])]).filter(e=>e.tone===`write`);t.forEach((e,n)=>{e.badge=`Write this down · ${n+1} of ${t.length}`,e.badgeFr=`Écris ceci · ${n+1} sur ${t.length}`,e.badgeHe=`העתיקו למחברת · ${n+1} מתוך ${t.length}`});let n=e.filter(e=>e.check||e.activity).length;return e[0].chips=[{icon:`Pencil`,text:`${t.length} things to write down`,textFr:`${t.length} choses à écrire`,textHe:`${t.length} דברים להעתיק`},{icon:`HelpCircle`,text:`${n} questions to answer`,textFr:`${n} questions`,textHe:`${n} שאלות לענות עליהן`}],e}var p=f(d),m=`#0087a8`,h=`#5c2483`,g=`#c25e12`,_=`#4a8b23`,v=`#1a5fa8`,y=(e,t,n)=>`${e}\\dfrac{${t}}{${n}}`,b=f([{layout:`hero`,color:v,icon:`Combine`,brand:`Year 7 Mathematics`,brandFr:`Maths 7e année`,brandHe:`מתמטיקה · Year 7`,eyebrow:`Unit 7 · 7.2 · Lesson 2`,eyebrowFr:`Unité 7 · 7.2 · Leçon 2`,eyebrowHe:`יחידה 7 · 7.2 · שיעור 2`,title:`Adding Mixed Numbers`,titleFr:`Additionner des nombres mixtes`,titleHe:`חיבור מספרים מעורבים`,compact:!0,objective:`Estimate first, add mixed numbers (wholes, then fractions), make a new whole, and finish the answer.`,objectiveFr:`Estimer d’abord, additionner des nombres mixtes (les entiers, puis les fractions), faire un nouvel entier, et terminer la réponse.`,objectiveHe:`לעשות אומדן קודם, לחבר מספרים מעורבים (השלמים ואז השברים), ליצור שלם חדש, ולסיים את התשובה.`,card:{icon:`Lightbulb`,badge:`The big idea`,badgeFr:`L’idée clé`,badgeHe:`הרעיון המרכזי`,text:`**Wholes** with wholes, **fractions** with fractions. Extra pieces can make a **new whole**.`,textFr:`Les **entiers** avec les entiers, les **fractions** avec les fractions. Des parts en trop peuvent faire un **nouvel entier**.`,textHe:`**שלמים** עם שלמים, **שברים** עם שברים. חתיכות עודפות יכולות ליצור **שלם חדש**.`}},{layout:`split`,accent:g,icon:`Circle`,eyebrow:`Think first`,eyebrowFr:`Réfléchis d’abord`,eyebrowHe:`קודם חושבים`,title:`Friday and Saturday`,titleFr:`Vendredi et samedi`,titleHe:`שישי ושבת`,ratio:50,inlineSvg:i.STARTER_PIZZAS,content:`Mr Bowen eats $${y(1,3,4)}$ pizzas on Friday and $${y(2,3,4)}$ pizzas on Saturday.`,contentFr:`M. Bowen mange $${y(1,3,4)}$ pizzas le vendredi et $${y(2,3,4)}$ pizzas le samedi.`,contentHe:`מר בואן אוכל $${y(1,3,4)}$ פיצות ביום שישי ו-$${y(2,3,4)}$ פיצות בשבת.`,check:{id:`chk_friday`,q:`How many pizzas is that?`,qFr:`Combien de pizzas en tout ?`,qHe:`כמה פיצות זה?`,options:[{val:`A`,text:`$${y(3,6,8)}$`},{val:`B`,text:`$${y(3,6,4)}$`},{val:`C`,text:`$${y(4,1,2)}$`}],correct:`C`,expEn:`$1 + 2 = 3$ wholes. $\\dfrac{3}{4} + \\dfrac{3}{4} = \\dfrac{6}{4}$: that is **more than one whole**, $1\\dfrac{2}{4} = 1\\dfrac{1}{2}$. So $3 + 1\\dfrac{1}{2} = 4\\dfrac{1}{2}$. A adds the bottoms. B is not finished: 6 quarters are more than a pizza.`,expFr:`$1 + 2 = 3$ entiers. $\\dfrac{3}{4} + \\dfrac{3}{4} = \\dfrac{6}{4}$ : c’est **plus d’un entier**, $1\\dfrac{2}{4} = 1\\dfrac{1}{2}$. Donc $3 + 1\\dfrac{1}{2} = 4\\dfrac{1}{2}$. A additionne les bas. B n’est pas terminée : 6 quarts, c’est plus d’une pizza.`,expHe:`$1 + 2 = 3$ שלמים. $\\dfrac{3}{4} + \\dfrac{3}{4} = \\dfrac{6}{4}$: זה **יותר משלם אחד**, $1\\dfrac{2}{4} = 1\\dfrac{1}{2}$. ולכן $3 + 1\\dfrac{1}{2} = 4\\dfrac{1}{2}$. A מחבר את המכנים. B לא גמור: 6 רבעים זה יותר מפיצה.`}},{layout:`split`,accent:v,icon:`Combine`,eyebrow:`Wholes, then fractions`,eyebrowFr:`Les entiers, puis les fractions`,eyebrowHe:`שלמים, ואז שברים`,title:`Collecting Like Terms`,titleFr:`Regrouper les termes semblables`,titleHe:`כינוס איברים דומים`,ratio:50,inlineSvg:i.SPLIT_METHOD,content:`Wholes with wholes. Fractions with fractions.`,contentFr:`Les entiers avec les entiers. Les fractions avec les fractions.`,contentHe:`שלמים עם שלמים. שברים עם שברים.`,notes:[{tone:`write`,text:`**Adding mixed numbers:**
1 Add the whole numbers.
2 Add the fractions.
3 Put them together.`,textFr:`**Additionner des nombres mixtes (adding mixed numbers) :**
1 Additionne les nombres entiers.
2 Additionne les fractions.
3 Mets-les ensemble.`,textHe:`**חיבור מספרים מעורבים (adding mixed numbers):**
1 מחברים את המספרים השלמים.
2 מחברים את השברים.
3 מחברים את שניהם יחד.`},{tone:`tip`,badge:`From Unit 2`,badgeFr:`Vu en unité 2`,badgeHe:`מיחידה 2`,text:`This is **collecting like terms**, like $2x + 3y + x = 3x + 3y$.`,textFr:`C’est **regrouper les termes semblables** (collecting like terms), comme $2x + 3y + x = 3x + 3y$.`,textHe:`זה **כינוס איברים דומים** (collecting like terms), כמו $2x + 3y + x = 3x + 3y$.`}]},{layout:`split`,accent:m,icon:`Target`,eyebrow:`English check`,eyebrowFr:`Point d’anglais`,eyebrowHe:`רגע של אנגלית`,title:`Estimate First`,titleFr:`Estime d’abord`,titleHe:`קודם אומדן`,ratio:55,inlineSvg:i.ESTIMATE,content:`**Estimate** = a quick answer: add the whole numbers.
**Between 5 and 6** = more than 5, less than 6.`,contentFr:`**Estimate** (estimer) = une réponse rapide : additionne les nombres entiers.
**Between 5 and 6** (entre 5 et 6) = plus que 5, moins que 6.`,contentHe:`**Estimate** (אומדן) = תשובה מהירה: מחברים את המספרים השלמים.
**Between 5 and 6** (בין 5 ל-6) = יותר מ-5, פחות מ-6.`,check:{id:`chk_estimate`,q:`Estimate $${y(2,3,10)} + ${y(5,4,10)}$. It is between…`,qFr:`Estime $${y(2,3,10)} + ${y(5,4,10)}$. C’est entre…`,qHe:`עשו אומדן ל-$${y(2,3,10)} + ${y(5,4,10)}$. זה בין…`,options:[{val:`A`,text:`2 and 5`,textFr:`2 et 5`,textHe:`2 ל-5`},{val:`B`,text:`7 and 8`,textFr:`7 et 8`,textHe:`7 ל-8`},{val:`C`,text:`8 and 9`,textFr:`8 et 9`,textHe:`8 ל-9`}],correct:`B`,expEn:`$2 + 5 = 7$. Both fractions are less than a half, so they make less than 1: the answer is **between 7 and 8**. A uses the two whole numbers; it does not add them.`,expFr:`$2 + 5 = 7$. Les deux fractions font moins d’une demie, donc moins de 1 ensemble : la réponse est **entre 7 et 8**. A prend les deux nombres entiers sans les additionner.`,expHe:`$2 + 5 = 7$. שני השברים פחות מחצי, אז יחד הם פחות מ-1: התשובה **בין 7 ל-8**. A לוקח את שני המספרים השלמים בלי לחבר אותם.`}},{layout:`split`,accent:m,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Estimate, Then Add`,titleFr:`Estime, puis additionne`,titleHe:`אומדן, ואז חיבור`,ratio:40,content:`Say the estimate first: **between** which two whole numbers? Then add.`,contentFr:`Dis d’abord l’estimation : **entre** quels nombres entiers ? Puis additionne.`,contentHe:`קודם אמרו את האומדן: **בין** אילו שני מספרים שלמים? אחר כך חברו.`,activity:{id:`act_plain`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`3 1/7 + 2 4/7 = [5] [5]/7`,`4 1/3 + 1 1/3 = [5] [2]/3`,`2 3/10 + 5 4/10 = [7] [7]/10`,`1 2/9 + 6 5/9 = [7] [7]/9`],split:2,explain:`**a** and **b** are between 5 and 6. **c** and **d** are between 7 and 8. In each one the fractions make less than 1, so nothing more to do.`,explainFr:`**a** et **b** sont entre 5 et 6. **c** et **d** sont entre 7 et 8. Dans chacune, les fractions font moins de 1 : rien d’autre à faire.`,explainHe:`**a** ו-**b** בין 5 ל-6. **c** ו-**d** בין 7 ל-8. בכל אחד מהם השברים יחד פחות מ-1, אז אין עוד מה לעשות.`}},{layout:`split`,accent:h,icon:`Scissors`,eyebrow:`Finish it`,eyebrowFr:`Termine`,eyebrowHe:`מסיימים`,title:`Simplest Form, Again`,titleFr:`Encore la forme la plus simple`,titleHe:`שוב הצורה המצומצמת`,ratio:50,inlineSvg:i.SIMPLEST,content:`$${y(2,6,10)} = ${y(2,3,5)}$: the same amount, with the smallest numbers.`,contentFr:`$${y(2,6,10)} = ${y(2,3,5)}$ : la même quantité, avec les plus petits nombres.`,contentHe:`$${y(2,6,10)} = ${y(2,3,5)}$: אותה כמות, עם המספרים הקטנים ביותר.`,notes:[{tone:`tip`,badge:`From Lesson 1`,badgeFr:`Vu en leçon 1`,badgeHe:`משיעור 1`,text:`Divide the top and the bottom by the same number. **The whole number does not change.**`,textFr:`Divise le haut et le bas par le même nombre. **Le nombre entier ne change pas.**`,textHe:`מחלקים את המונה ואת המכנה באותו מספר. **המספר השלם לא משתנה.**`}],activity:{id:`act_simplest`,type:`fill`,prompt:`Add. Then write it in its simplest form.`,promptFr:`Additionne. Puis écris-la sous sa forme la plus simple.`,promptHe:`חברו. אחר כך כתבו בצורה המצומצמת.`,lines:[`1 3/8 + 2 1/8 = [3] [4]/8 = [3] [1]/[2]`],explain:`$1 + 2 = 3$ and $\\dfrac{3}{8} + \\dfrac{1}{8} = \\dfrac{4}{8}$. Then $\\dfrac{4}{8} = \\dfrac{1}{2}$ (÷ 4): $3\\dfrac{1}{2}$.`,explainFr:`$1 + 2 = 3$ et $\\dfrac{3}{8} + \\dfrac{1}{8} = \\dfrac{4}{8}$. Puis $\\dfrac{4}{8} = \\dfrac{1}{2}$ (÷ 4) : $3\\dfrac{1}{2}$.`,explainHe:`$1 + 2 = 3$ ו-$\\dfrac{3}{8} + \\dfrac{1}{8} = \\dfrac{4}{8}$. ואז $\\dfrac{4}{8} = \\dfrac{1}{2}$ $(\\div 4)$: $3\\dfrac{1}{2}$.`}},{layout:`split`,accent:_,icon:`Circle`,eyebrow:`A new whole`,eyebrowFr:`Un nouvel entier`,eyebrowHe:`שלם חדש`,title:`More Than One Whole`,titleFr:`Plus d’un entier`,titleHe:`יותר משלם אחד`,ratio:50,inlineSvg:i.MORE_THAN_ONE,content:`Both fractions are **more than a half**, so they make **more than 1**.`,contentFr:`Les deux fractions font **plus d’une demie**, donc elles font **plus de 1**.`,contentHe:`שני השברים **יותר מחצי**, אז יחד הם **יותר מ-1**.`,notes:[{tone:`write`,text:`**More than one whole:** change the fraction to a mixed number. Then add it to the wholes.\n$${y(2,4,5)} + ${y(3,4,5)} = 5 + ${y(1,3,5)} = ${y(6,3,5)}$`,textFr:`**Plus d’un entier (more than one whole) :** écris la fraction en nombre mixte. Puis ajoute-la aux entiers.\n$${y(2,4,5)} + ${y(3,4,5)} = 5 + ${y(1,3,5)} = ${y(6,3,5)}$`,textHe:`**יותר משלם אחד (more than one whole):** הופכים את השבר למספר מעורב. אחר כך מוסיפים אותו לשלמים.\n$${y(2,4,5)} + ${y(3,4,5)} = 5 + ${y(1,3,5)} = ${y(6,3,5)}$`}]},{layout:`split`,accent:_,icon:`Scale`,eyebrow:`Which is right?`,eyebrowFr:`Laquelle est juste ?`,eyebrowHe:`מה נכון?`,title:`Three Thirds Make a Whole`,titleFr:`Trois tiers font un entier`,titleHe:`שלושה שלישים הם שלם`,ratio:45,content:`Add: $${y(3,2,3)} + ${y(1,2,3)}$`,contentFr:`Additionne : $${y(3,2,3)} + ${y(1,2,3)}$`,contentHe:`חברו: $${y(3,2,3)} + ${y(1,2,3)}$`,check:{id:`chk_thirds`,q:`Which answer is right?`,qFr:`Quelle réponse est juste ?`,qHe:`איזו תשובה נכונה?`,options:[{val:`A`,text:`$${y(4,4,6)}$`},{val:`B`,text:`$${y(5,1,3)}$`},{val:`C`,text:`$${y(4,4,3)}$`}],correct:`B`,expEn:`$3 + 1 = 4$. $\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$: three thirds make a whole, with one third left. $4 + 1\\dfrac{1}{3} = 5\\dfrac{1}{3}$. A added the bottoms. C is not finished.`,expFr:`$3 + 1 = 4$. $\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$ : trois tiers font un entier, et il reste un tiers. $4 + 1\\dfrac{1}{3} = 5\\dfrac{1}{3}$. A a additionné les bas. C n’est pas terminée.`,expHe:`$3 + 1 = 4$. $\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$: שלושה שלישים הם שלם, ונשאר שליש אחד. $4 + 1\\dfrac{1}{3} = 5\\dfrac{1}{3}$. A חיבר את המכנים. C לא גמור.`}},{layout:`split`,accent:_,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Add These`,titleFr:`Additionne`,titleHe:`חברו`,ratio:35,content:`Write each answer in its **simplest form**.
**b**, **c** and **d** make a new whole.`,contentFr:`Écris chaque réponse sous sa **forme la plus simple**.
**b**, **c** et **d** font un nouvel entier.`,contentHe:`כתבו כל תשובה **בצורה המצומצמת**.
ב-**b**, ב-**c** וב-**d** נוצר שלם חדש.`,activity:{id:`act_carry`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`2 5/8 + 3 1/8 = [5] [6]/8 = [5] [3]/[4]`,`1 4/5 + 4 2/5 = 5 + [6]/5 = [6] [1]/5`,`3 5/6 + 2 5/6 = 5 + [10]/6 = [6] [2]/[3]`,{q:`6 7/10 + 1 9/10 = 7 + [16]/10 = [8] [3]/[5]`,hint:`16/10 = 1 6/10. Then 6/10 = 3/5. Add the 1 to the 7.`,hintFr:`16/10 = 1 6/10. Puis 6/10 = 3/5. Ajoute le 1 au 7.`,hintHe:`16/10 = 1 6/10. ואז 6/10 = 3/5. הוסיפו את ה-1 ל-7.`}],split:4,explain:`**a** $\\dfrac{6}{8} = \\dfrac{3}{4}$. **b** $\\dfrac{6}{5} = 1\\dfrac{1}{5}$, and $5 + 1\\dfrac{1}{5} = 6\\dfrac{1}{5}$. **c** $\\dfrac{10}{6} = 1\\dfrac{4}{6} = 1\\dfrac{2}{3}$. **d** $\\dfrac{16}{10} = 1\\dfrac{6}{10} = 1\\dfrac{3}{5}$.`,explainFr:`**a** $\\dfrac{6}{8} = \\dfrac{3}{4}$. **b** $\\dfrac{6}{5} = 1\\dfrac{1}{5}$, et $5 + 1\\dfrac{1}{5} = 6\\dfrac{1}{5}$. **c** $\\dfrac{10}{6} = 1\\dfrac{4}{6} = 1\\dfrac{2}{3}$. **d** $\\dfrac{16}{10} = 1\\dfrac{6}{10} = 1\\dfrac{3}{5}$.`,explainHe:`**a** $\\dfrac{6}{8} = \\dfrac{3}{4}$. **b** $\\dfrac{6}{5} = 1\\dfrac{1}{5}$, ו-$5 + 1\\dfrac{1}{5} = 6\\dfrac{1}{5}$. **c** $\\dfrac{10}{6} = 1\\dfrac{4}{6} = 1\\dfrac{2}{3}$. **d** $\\dfrac{16}{10} = 1\\dfrac{6}{10} = 1\\dfrac{3}{5}$.`}},{layout:`split`,accent:g,icon:`Scissors`,eyebrow:`Different denominators`,eyebrowFr:`Dénominateurs différents`,eyebrowHe:`מכנים שונים`,title:`Same Size Slices`,titleFr:`Des parts de même taille`,titleHe:`חתיכות באותו גודל`,ratio:45,inlineSvg:i.SAME_BOTTOM,content:`Add only pieces of **the same size**. Change the fractions; the wholes stay as they are.`,contentFr:`Additionne seulement des parts de **même taille**. Transforme les fractions ; les entiers ne changent pas.`,contentHe:`מחברים רק חתיכות **באותו גודל**. מרחיבים את השברים; השלמים נשארים כמו שהם.`,notes:[{tone:`tip`,badge:`From Lesson 1`,badgeFr:`Vu en leçon 1`,badgeHe:`משיעור 1`,text:`Make the bottoms the same first: the LCM. Then add the tops. Never add the bottoms.`,textFr:`Mets d’abord le même bas : le PPCM. Puis additionne les hauts. N’additionne jamais les bas.`,textHe:`קודם מביאים לאותו מכנה: הכמק"ב. אחר כך מחברים את המונים. אף פעם לא מחברים את המכנים.`}],activity:{id:`act_same_size`,type:`fill`,prompt:`Change the fractions. Then add.`,promptFr:`Transforme les fractions. Puis additionne.`,promptHe:`הרחיבו את השברים. אחר כך חברו.`,lines:[`3 1/4 + 1 5/8 = 4 + [2]/8 + 5/8 = [4] [7]/8`,`2 1/2 + 1 1/3 = 3 + [3]/6 + [2]/6 = [3] [5]/6`],split:2,explain:`**a** 8 is in the 4 times table: $\\dfrac{1}{4} = \\dfrac{2}{8}$. **b** Both change to sixths: $\\dfrac{1}{2} = \\dfrac{3}{6}$ and $\\dfrac{1}{3} = \\dfrac{2}{6}$.`,explainFr:`**a** 8 est dans la table de 4 : $\\dfrac{1}{4} = \\dfrac{2}{8}$. **b** Les deux deviennent des sixièmes : $\\dfrac{1}{2} = \\dfrac{3}{6}$ et $\\dfrac{1}{3} = \\dfrac{2}{6}$.`,explainHe:`**a** 8 נמצא בלוח הכפל של 4: $\\dfrac{1}{4} = \\dfrac{2}{8}$. **b** שניהם הופכים לשישיות: $\\dfrac{1}{2} = \\dfrac{3}{6}$ ו-$\\dfrac{1}{3} = \\dfrac{2}{6}$.`}},{layout:`split`,accent:g,icon:`Pencil`,eyebrow:`Your turn`,eyebrowFr:`À toi`,eyebrowHe:`תורכם`,title:`Make Them the Same`,titleFr:`Mets-les pareil`,titleHe:`הביאו לאותו מכנה`,ratio:35,content:`**a** to **c**: change one fraction.
**d**: change both to sixths, then make a new whole.`,contentFr:`**a** à **c** : transforme une fraction.
**d** : les deux en sixièmes, puis fais un nouvel entier.`,contentHe:`**a** עד **c**: מרחיבים שבר אחד.
**d**: את שניהם לשישיות, ואז יוצרים שלם חדש.`,activity:{id:`act_diff_mixed`,type:`fill`,prompt:`Fill every box. Then press Check.`,promptFr:`Remplis chaque case. Puis appuie sur Vérifier.`,promptHe:`מלאו כל תיבה. אחר כך לחצו על בדיקה.`,lines:[`1 1/2 + 4 3/8 = [5] [7]/8`,`2 1/3 + 3 4/9 = [5] [7]/9`,`4 3/4 + 1 3/8 = 5 + [9]/8 = [6] [1]/8`,{q:`1 1/2 + 2 2/3 = 3 + [7]/6 = [4] [1]/6`,hint:`1/2 = 3/6 and 2/3 = 4/6. 3/6 + 4/6 = 7/6, more than 1.`,hintFr:`1/2 = 3/6 et 2/3 = 4/6. 3/6 + 4/6 = 7/6, plus de 1.`,hintHe:`1/2 = 3/6 ו-2/3 = 4/6. 3/6 + 4/6 = 7/6, יותר מ-1.`}],split:4,explain:`**a** $\\dfrac{4}{8} + \\dfrac{3}{8}$. **b** $\\dfrac{3}{9} + \\dfrac{4}{9}$. **c** $\\dfrac{6}{8} + \\dfrac{3}{8} = \\dfrac{9}{8} = 1\\dfrac{1}{8}$. **d** $\\dfrac{3}{6} + \\dfrac{4}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$.`,explainFr:`**a** $\\dfrac{4}{8} + \\dfrac{3}{8}$. **b** $\\dfrac{3}{9} + \\dfrac{4}{9}$. **c** $\\dfrac{6}{8} + \\dfrac{3}{8} = \\dfrac{9}{8} = 1\\dfrac{1}{8}$. **d** $\\dfrac{3}{6} + \\dfrac{4}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$.`,explainHe:`**a** $\\dfrac{4}{8} + \\dfrac{3}{8}$. **b** $\\dfrac{3}{9} + \\dfrac{4}{9}$. **c** $\\dfrac{6}{8} + \\dfrac{3}{8} = \\dfrac{9}{8} = 1\\dfrac{1}{8}$. **d** $\\dfrac{3}{6} + \\dfrac{4}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$.`}},{layout:`split`,accent:h,icon:`Scale`,eyebrow:`Right or wrong?`,eyebrowFr:`Juste ou faux ?`,eyebrowHe:`נכון או לא נכון?`,title:`Check Mr Bowen’s Work`,titleFr:`Vérifie le travail de M. Bowen`,titleHe:`בדקו את העבודה של מר בואן`,ratio:40,content:`In class: **arms up** if he is right, **arms down** if he is wrong. Two of these are wrong.`,contentFr:`En classe : **bras en haut** s’il a raison, **bras en bas** s’il a tort. Deux sont fausses.`,contentHe:`בכיתה: **ידיים למעלה** אם הוא צודק, **ידיים למטה** אם הוא טועה. שניים מהם לא נכונים.`,check:{id:`chk_right_wrong`,q:`Which of Mr Bowen’s answers is **right**?`,qFr:`Quelle réponse de M. Bowen est **juste** ?`,qHe:`איזו תשובה של מר בואן **נכונה**?`,options:[{val:`A`,text:`$${y(1,2,5)} + ${y(2,2,5)} = ${y(3,4,10)}$`},{val:`B`,text:`$${y(2,3,4)} + ${y(2,3,4)} = ${y(4,1,2)}$`},{val:`C`,text:`$${y(4,1,2)} + ${y(1,1,4)} = ${y(5,3,4)}$`}],correct:`C`,expEn:`C: $\\dfrac{1}{2} = \\dfrac{2}{4}$, so $5 + \\dfrac{3}{4} = 5\\dfrac{3}{4}$. A added the bottoms: it is $3\\dfrac{4}{5}$. B lost the new whole: $4 + 1\\dfrac{1}{2} = 5\\dfrac{1}{2}$.`,expFr:`C : $\\dfrac{1}{2} = \\dfrac{2}{4}$, donc $5 + \\dfrac{3}{4} = 5\\dfrac{3}{4}$. A a additionné les bas : c’est $3\\dfrac{4}{5}$. B a perdu le nouvel entier : $4 + 1\\dfrac{1}{2} = 5\\dfrac{1}{2}$.`,expHe:`C: $\\dfrac{1}{2} = \\dfrac{2}{4}$, ולכן $5 + \\dfrac{3}{4} = 5\\dfrac{3}{4}$. A חיבר את המכנים: התשובה $3\\dfrac{4}{5}$. B איבד את השלם החדש: $4 + 1\\dfrac{1}{2} = 5\\dfrac{1}{2}$.`}},{layout:`split`,accent:v,icon:`BookOpen`,eyebrow:`English check`,eyebrowFr:`Point d’anglais`,eyebrowHe:`רגע של אנגלית`,title:`Is He Correct?`,titleFr:`A-t-il raison ?`,titleHe:`האם הוא צודק?`,ratio:50,inlineSvg:i.BOOK_WORDS,content:`The Workbook asks: **Is he correct? Explain your answer.** Answer **Yes, because …** or **No, because …**\n\nMr Bowen says: $${y(2,1,2)} + ${y(1,1,2)} = 3$`,contentFr:`Le cahier demande : **Is he correct? Explain your answer.** (A-t-il raison ? Explique.) Réponds **Yes, because …** ou **No, because …**\n\nM. Bowen dit : $${y(2,1,2)} + ${y(1,1,2)} = 3$`,contentHe:`החוברת שואלת: **Is he correct? Explain your answer.** (האם הוא צודק? הסבירו.) עונים **Yes, because …** או **No, because …**\n\nמר בואן אומר: $${y(2,1,2)} + ${y(1,1,2)} = 3$`,check:{id:`chk_correct`,q:`Is he correct? Choose the best answer.`,qFr:`A-t-il raison ? Choisis la meilleure réponse.`,qHe:`האם הוא צודק? בחרו את התשובה הטובה ביותר.`,options:[{val:`A`,text:`Yes, because 2 + 1 = 3.`,textFr:`Yes, because 2 + 1 = 3. (Oui, car 2 + 1 = 3.)`,textHe:`Yes, because 2 + 1 = 3. (כן, כי 2 + 1 = 3.)`},{val:`B`,text:`No, because ½ + ½ = 1, so the answer is 4.`,textFr:`No, because ½ + ½ = 1, so the answer is 4. (Non, car ½ + ½ = 1, donc la réponse est 4.)`,textHe:`No, because ½ + ½ = 1, so the answer is 4. (לא, כי ½ + ½ = 1, אז התשובה היא 4.)`},{val:`C`,text:`No, because the answer is 3 2/4.`,textFr:`No, because the answer is 3 2/4. (Non, car la réponse est 3 2/4.)`,textHe:`No, because the answer is 3 2/4. (לא, כי התשובה היא 3 2/4.)`}],correct:`B`,expEn:`He forgot the fractions: $\\dfrac{1}{2} + \\dfrac{1}{2} = 1$, a new whole. So $2 + 1 + 1 = 4$. A explains only the wholes. C is the same amount as $3\\dfrac{1}{2}$, still wrong.`,expFr:`Il a oublié les fractions : $\\dfrac{1}{2} + \\dfrac{1}{2} = 1$, un nouvel entier. Donc $2 + 1 + 1 = 4$. A n’explique que les entiers. C vaut $3\\dfrac{1}{2}$, toujours faux.`,expHe:`הוא שכח את השברים: $\\dfrac{1}{2} + \\dfrac{1}{2} = 1$, שלם חדש. ולכן $2 + 1 + 1 = 4$. A מסביר רק את השלמים. C שווה ל-$3\\dfrac{1}{2}$, וגם זה לא נכון.`}},{layout:`split`,accent:_,icon:`Coffee`,eyebrow:`Word problem`,eyebrowFr:`Problème`,eyebrowHe:`בעיה מילולית`,title:`Mr Bowen’s Phở`,titleFr:`Le phở de M. Bowen`,titleHe:`הפו של מר בואן`,ratio:50,image:r,content:`Mr Bowen eats $${y(2,3,8)}$ bowls of phở for breakfast and $${y(1,5,8)}$ bowls for lunch. How many bowls is that **altogether**?`,contentFr:`M. Bowen mange $${y(2,3,8)}$ bols de phở au petit-déjeuner et $${y(1,5,8)}$ bols au déjeuner. Combien de bols **en tout** (altogether) ?`,contentHe:`מר בואן אוכל $${y(2,3,8)}$ קערות פו (מרק וייטנאמי) בארוחת הבוקר ו-$${y(1,5,8)}$ קערות בצהריים. כמה קערות זה **בסך הכול** (altogether)?`,activity:{id:`act_pho`,type:`fill`,prompt:`Add the wholes, then the fractions.`,promptFr:`Additionne les entiers, puis les fractions.`,promptHe:`חברו את השלמים, ואז את השברים.`,lines:[`2 3/8 + 1 5/8 = 3 + [8]/8 = [4]`],explain:`$\\dfrac{3}{8} + \\dfrac{5}{8} = \\dfrac{8}{8}$, exactly 1. $3 + 1 = 4$ bowls. He does not eat dinner.`,explainFr:`$\\dfrac{3}{8} + \\dfrac{5}{8} = \\dfrac{8}{8}$, exactement 1. $3 + 1 = 4$ bols. Il ne dîne pas.`,explainHe:`$\\dfrac{3}{8} + \\dfrac{5}{8} = \\dfrac{8}{8}$, בדיוק 1. $3 + 1 = 4$ קערות. הוא לא אוכל ארוחת ערב.`}},{layout:`split`,accent:_,icon:`Clock`,eyebrow:`Word problem`,eyebrowFr:`Problème`,eyebrowHe:`בעיה מילולית`,title:`Mr Bowen’s Cat`,titleFr:`Le chat de M. Bowen`,titleHe:`החתול של מר בואן`,ratio:50,image:a,content:`The cat sleeps $${y(7,1,2)}$ hours in the morning and $${y(8,3,4)}$ hours in the afternoon. Mr Bowen says: “My cat sleeps **more than** 16 hours.”`,contentFr:`Le chat dort $${y(7,1,2)}$ heures le matin et $${y(8,3,4)}$ heures l’après-midi. M. Bowen dit : « Mon chat dort **plus de** 16 heures. »`,contentHe:`החתול ישן $${y(7,1,2)}$ שעות בבוקר ו-$${y(8,3,4)}$ שעות אחר הצהריים. מר בואן אומר: "החתול שלי ישן **יותר מ**-16 שעות."`,check:{id:`chk_cat`,q:`Is he correct?`,qFr:`A-t-il raison ?`,qHe:`האם הוא צודק?`,options:[{val:`A`,text:`Yes, because it is $${y(16,1,4)}$ hours.`,textFr:`Oui, car ça fait $${y(16,1,4)}$ heures.`,textHe:`כן, כי זה $${y(16,1,4)}$ שעות.`},{val:`B`,text:`No, because it is $${y(15,4,6)}$ hours.`,textFr:`Non, car ça fait $${y(15,4,6)}$ heures.`,textHe:`לא, כי זה $${y(15,4,6)}$ שעות.`},{val:`C`,text:`No, because it is 15 hours.`,textFr:`Non, car ça fait 15 heures.`,textHe:`לא, כי זה 15 שעות.`}],correct:`A`,expEn:`$7 + 8 = 15$. $\\dfrac{1}{2} = \\dfrac{2}{4}$, and $\\dfrac{2}{4} + \\dfrac{3}{4} = \\dfrac{5}{4} = 1\\dfrac{1}{4}$. So $16\\dfrac{1}{4}$ hours: yes, more than 16. B added the bottoms; C forgot the fractions. Then it sleeps at night.`,expFr:`$7 + 8 = 15$. $\\dfrac{1}{2} = \\dfrac{2}{4}$, et $\\dfrac{2}{4} + \\dfrac{3}{4} = \\dfrac{5}{4} = 1\\dfrac{1}{4}$. Donc $16\\dfrac{1}{4}$ heures : oui, plus de 16. B a additionné les bas ; C a oublié les fractions. Ensuite, il dort la nuit.`,expHe:`$7 + 8 = 15$. $\\dfrac{1}{2} = \\dfrac{2}{4}$, ו-$\\dfrac{2}{4} + \\dfrac{3}{4} = \\dfrac{5}{4} = 1\\dfrac{1}{4}$. כלומר $16\\dfrac{1}{4}$ שעות: כן, יותר מ-16. B חיבר את המכנים; C שכח את השברים. ואחר כך הוא ישן בלילה.`}},{layout:`split`,accent:_,icon:`Triangle`,eyebrow:`Word problem`,eyebrowFr:`Problème`,eyebrowHe:`בעיה מילולית`,title:`The Cat’s Garden`,titleFr:`Le jardin du chat`,titleHe:`הגינה של החתול`,ratio:50,inlineSvg:i.FENCE,content:`The cat wants a triangle garden with a fence **all the way round**. Mr Bowen has **6 m** of fence. Is that **enough**?`,contentFr:`Le chat veut un jardin en triangle avec une clôture **tout autour**. M. Bowen a **6 m** de clôture. Est-ce **assez** (enough) ?`,contentHe:`החתול רוצה גינה משולשת עם גדר **מסביב**. למר בואן יש **6 מ'** של גדר. האם זה **מספיק** (enough)?`,activity:{id:`act_fence`,type:`fill`,prompt:`Add the three sides.`,promptFr:`Additionne les trois côtés.`,promptHe:`חברו את שלוש הצלעות.`,lines:[`2 1/3 + 2 1/3 + 1 2/3 = 5 + [4]/3 = [6] [1]/3`],explain:`$2 + 2 + 1 = 5$, and $\\dfrac{1}{3} + \\dfrac{1}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$. So $6\\dfrac{1}{3}$ m. **No, because** 6 m is $\\dfrac{1}{3}$ m short. The cat is waiting.`,explainFr:`$2 + 2 + 1 = 5$, et $\\dfrac{1}{3} + \\dfrac{1}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$. Donc $6\\dfrac{1}{3}$ m. **Non, car** il manque $\\dfrac{1}{3}$ m. Le chat attend.`,explainHe:`$2 + 2 + 1 = 5$, ו-$\\dfrac{1}{3} + \\dfrac{1}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$. כלומר $6\\dfrac{1}{3}$ מ'. **לא, כי** חסר $\\dfrac{1}{3}$ מ'. החתול מחכה.`}},{layout:`stack`,accent:v,icon:`ListChecks`,eyebrow:`Before you finish`,eyebrowFr:`Avant de finir`,eyebrowHe:`לפני שמסיימים`,title:`Can You Do These?`,titleFr:`Sais-tu faire ceci ?`,titleHe:`אתם יודעים לעשות את זה?`,items:[{text:`**Estimate first:** add the wholes. Between which two whole numbers?`,textFr:`**Estime d’abord :** additionne les entiers. Entre quels deux nombres entiers ?`,textHe:`**קודם אומדן:** מחברים את השלמים. בין אילו שני מספרים שלמים?`},{text:`**Wholes, then fractions:** make the bottoms the same if they are different.`,textFr:`**Les entiers, puis les fractions :** mets le même bas s’ils sont différents.`,textHe:`**שלמים, ואז שברים:** מביאים לאותו מכנה אם המכנים שונים.`},{text:`**A new whole:** change the fraction to a mixed number and add it to the wholes. Then the simplest form.`,textFr:`**Un nouvel entier :** écris la fraction en nombre mixte et ajoute-la aux entiers. Puis la forme la plus simple.`,textHe:`**שלם חדש:** הופכים את השבר למספר מעורב ומוסיפים לשלמים. אחר כך הצורה המצומצמת.`}],notes:[{tone:`homework`,text:`Two traps: adding the **bottoms**, and **losing the new whole** ($4\\dfrac{6}{4}$ is not finished).`,textFr:`Deux pièges : additionner les **bas**, et **perdre le nouvel entier** ($4\\dfrac{6}{4}$ n’est pas terminé).`,textHe:`שתי מלכודות: לחבר את **המכנים**, ו**לאבד את השלם החדש** ($4\\dfrac{6}{4}$ לא גמור).`}]},{layout:`hero`,color:m,icon:`CheckCircle2`,title:`Lesson Complete!`,titleFr:`Leçon terminée !`,titleHe:`השיעור הסתיים!`,subtitle:`Now practise **Mixed numbers**. Then the quiz.`,subtitleFr:`Maintenant, entraîne-toi : **Nombres mixtes**. Puis le quiz.`,subtitleHe:`עכשיו תרגלו **מספרים מעורבים**. אחר כך הבוחן.`}]),x={timeLimit:900,passages:[],questions:[{id:`a1_same`,type:`mcq`,title:`1. $$\\dfrac{2}{7} + \\dfrac{3}{7} = $$ ?`,titleHe:`1. $$\\dfrac{2}{7} + \\dfrac{3}{7} = $$ ?`,options:[{val:`A`,text:`A. $$\\dfrac{5}{14}$$`},{val:`B`,text:`B. $$\\dfrac{5}{7}$$`},{val:`C`,text:`C. $$\\dfrac{6}{7}$$`},{val:`D`,text:`D. $$\\dfrac{5}{49}$$`}],correct:`B`,expEn:`The same denominator: add the tops, keep the bottom. 2 sevenths + 3 sevenths = **5 sevenths**. A adds the bottoms too; C multiplies the tops; D multiplies the bottoms.`,expFr:`Même dénominateur : additionne les hauts, garde le bas. 2 septièmes + 3 septièmes = **5 septièmes**. A additionne aussi les bas ; C multiplie les hauts ; D multiplie les bas.`,expHe:`אותו מכנה: מחברים את המונים, המכנה נשאר. 2 שביעיות + 3 שביעיות = **5 שביעיות**. A מחבר גם את המכנים; C כופל את המונים; D כופל את המכנים.`},{id:`a2_simplest`,type:`fill_blank`,title:`2. Add $$\\dfrac{3}{10} + \\dfrac{5}{10}$$. Write the answer in its simplest form. Type the top.`,titleHe:`2. חברו $$\\dfrac{3}{10} + \\dfrac{5}{10}$$. כתבו את התשובה בצורה המצומצמת. כתבו את המונה.`,textParts:[`$$\\dfrac{3}{10} + \\dfrac{5}{10} = \\dfrac{8}{10} = $$ `,` fifths`],textPartsHe:[`$$\\dfrac{3}{10} + \\dfrac{5}{10} = \\dfrac{8}{10} = $$ `,` חמישיות`],blanks:{1:{correct:`4`}},expEn:`$$\\dfrac{8}{10}$$: 8 and 10 both divide by 2, so $$\\dfrac{8}{10} = \\dfrac{4}{5}$$, four fifths.`,expFr:`$$\\dfrac{8}{10}$$ : 8 et 10 se divisent par 2, donc $$\\dfrac{8}{10} = \\dfrac{4}{5}$$, quatre cinquièmes.`,expHe:`$$\\dfrac{8}{10}$$: אפשר לחלק את 8 ואת 10 ב-2, ולכן $$\\dfrac{8}{10} = \\dfrac{4}{5}$$, ארבע חמישיות.`},{id:`a3_mixed`,type:`mcq`,title:`3. $$\\dfrac{7}{9} + \\dfrac{5}{9}$$ as a mixed number in its simplest form:`,titleHe:`3. $$\\dfrac{7}{9} + \\dfrac{5}{9}$$ כמספר מעורב בצורה המצומצמת:`,options:[{val:`A`,text:`A. $$\\dfrac{12}{18}$$`},{val:`B`,text:`B. $$1\\dfrac{1}{3}$$`},{val:`C`,text:`C. $$1\\dfrac{3}{9}$$`},{val:`D`,text:`D. $$\\dfrac{12}{9}$$`}],correct:`B`,expEn:`$$\\dfrac{7}{9} + \\dfrac{5}{9} = \\dfrac{12}{9} = 1\\dfrac{3}{9} = 1\\dfrac{1}{3}$$ (÷ 3). C and D are the same amount but not finished; A adds the bottoms.`,expFr:`$$\\dfrac{7}{9} + \\dfrac{5}{9} = \\dfrac{12}{9} = 1\\dfrac{3}{9} = 1\\dfrac{1}{3}$$ (÷ 3). C et D sont la même quantité mais pas terminées ; A additionne les bas.`,expHe:`$$\\dfrac{7}{9} + \\dfrac{5}{9} = \\dfrac{12}{9} = 1\\dfrac{3}{9} = 1\\dfrac{1}{3}$$ $$(\\div 3)$$. C ו-D הם אותה כמות אבל לא גמורים; A מחבר את המכנים.`},{id:`a4_lcm`,type:`mcq`,title:`4. What is the lowest common denominator for $$\\dfrac{2}{9} + \\dfrac{1}{6}$$?`,titleHe:`4. מהו המכנה המשותף הקטן ביותר של $$\\dfrac{2}{9} + \\dfrac{1}{6}$$?`,options:[{val:`A`,text:`A. $$15$$`},{val:`B`,text:`B. $$18$$`},{val:`C`,text:`C. $$54$$`},{val:`D`,text:`D. $$9$$`}],correct:`B`,expEn:`The 9 times table: 9, **18**, 27 … 18 is in the 6 times table too: the LCM. 54 = 9 × 6 works, with bigger numbers. 15 = 9 + 6 is in neither table; 9 is not in the 6 times table.`,expFr:`La table de 9 : 9, **18**, 27 … 18 est aussi dans la table de 6 : c’est le PPCM. 54 = 9 × 6 marche, avec de plus grands nombres. 15 = 9 + 6 n’est dans aucune des deux tables ; 9 n’est pas dans la table de 6.`,expHe:`לוח הכפל של 9: $$9, 18, 27$$ … 18 נמצא גם בלוח הכפל של 6: זה הכמק"ב. $$54 = 9 \\times 6$$ עובד, עם מספרים גדולים יותר. $$15 = 9 + 6$$ לא נמצא באף לוח; 9 לא נמצא בלוח הכפל של 6.`},{id:`a5_different`,type:`fill_blank`,title:`5. Add $$\\dfrac{2}{5} + \\dfrac{1}{3}$$. Type the top.`,titleHe:`5. חברו $$\\dfrac{2}{5} + \\dfrac{1}{3}$$. כתבו את המונה.`,textParts:[`$$\\dfrac{2}{5} + \\dfrac{1}{3} = $$ `,` fifteenths`],textPartsHe:[`$$\\dfrac{2}{5} + \\dfrac{1}{3} = $$ `,` חלקי 15`],blanks:{1:{correct:`11`}},expEn:`The LCM of 5 and 3 is 15. $$\\dfrac{2}{5} = \\dfrac{6}{15}$$ (× 3) and $$\\dfrac{1}{3} = \\dfrac{5}{15}$$ (× 5). $$6 + 5 = 11$$: $$\\dfrac{11}{15}$$.`,expFr:`Le PPCM de 5 et 3 est 15. $$\\dfrac{2}{5} = \\dfrac{6}{15}$$ (× 3) et $$\\dfrac{1}{3} = \\dfrac{5}{15}$$ (× 5). $$6 + 5 = 11$$ : $$\\dfrac{11}{15}$$.`,expHe:`הכמק"ב של 5 ו-3 הוא 15. $$\\dfrac{2}{5} = \\dfrac{6}{15}$$ $$(\\times 3)$$ ו-$$\\dfrac{1}{3} = \\dfrac{5}{15}$$ $$(\\times 5)$$. $$6 + 5 = 11$$: $$\\dfrac{11}{15}$$.`},{id:`a6_one_changes`,type:`mcq`,title:`6. $$\\dfrac{5}{12} + \\dfrac{1}{3}$$ in its simplest form:`,titleHe:`6. $$\\dfrac{5}{12} + \\dfrac{1}{3}$$ בצורה המצומצמת:`,options:[{val:`A`,text:`A. $$\\dfrac{6}{15}$$`},{val:`B`,text:`B. $$\\dfrac{3}{4}$$`},{val:`C`,text:`C. $$\\dfrac{9}{12}$$`},{val:`D`,text:`D. $$\\dfrac{6}{12}$$`}],correct:`B`,expEn:`12 is in the 3 times table: $$\\dfrac{1}{3} = \\dfrac{4}{12}$$. $$\\dfrac{5}{12} + \\dfrac{4}{12} = \\dfrac{9}{12} = \\dfrac{3}{4}$$ (÷ 3). A adds the tops and the bottoms; C is not finished; D did not change the top.`,expFr:`12 est dans la table de 3 : $$\\dfrac{1}{3} = \\dfrac{4}{12}$$. $$\\dfrac{5}{12} + \\dfrac{4}{12} = \\dfrac{9}{12} = \\dfrac{3}{4}$$ (÷ 3). A additionne les hauts et les bas ; C n’est pas terminée ; D n’a pas changé le haut.`,expHe:`12 נמצא בלוח הכפל של 3: $$\\dfrac{1}{3} = \\dfrac{4}{12}$$. $$\\dfrac{5}{12} + \\dfrac{4}{12} = \\dfrac{9}{12} = \\dfrac{3}{4}$$ $$(\\div 3)$$. A מחבר את המונים ואת המכנים; C לא גמור; D לא שינה את המונה.`},{id:`a7_more_than_one`,type:`mcq`,title:`7. Which sum is more than 1?`,titleHe:`7. איזה סכום יותר מ-1?`,options:[{val:`A`,text:`A. $$\\dfrac{3}{7} + \\dfrac{2}{5}$$`},{val:`B`,text:`B. $$\\dfrac{4}{7} + \\dfrac{5}{8}$$`},{val:`C`,text:`C. $$\\dfrac{1}{3} + \\dfrac{2}{5}$$`},{val:`D`,text:`D. $$\\dfrac{4}{9} + \\dfrac{1}{2}$$`}],correct:`B`,expEn:`$$\\dfrac{4}{7}$$ and $$\\dfrac{5}{8}$$ are both more than a half, so together they are more than 1. In A and C both are less than a half. In D, $$\\dfrac{4}{9}$$ is a little less than a half: $$\\dfrac{17}{18}$$.`,expFr:`$$\\dfrac{4}{7}$$ et $$\\dfrac{5}{8}$$ font tous les deux plus d’une demie, donc ensemble plus de 1. Dans A et C, les deux font moins d’une demie. Dans D, $$\\dfrac{4}{9}$$ est un peu moins qu’une demie : $$\\dfrac{17}{18}$$.`,expHe:`$$\\dfrac{4}{7}$$ ו-$$\\dfrac{5}{8}$$ שניהם יותר מחצי, אז יחד הם יותר מ-1. ב-A וב-C שניהם פחות מחצי. ב-D, $$\\dfrac{4}{9}$$ קצת פחות מחצי: $$\\dfrac{17}{18}$$.`},{id:`a8_add_mixed`,type:`fill_blank`,title:`8. Add $$4\\dfrac{1}{5} + 2\\dfrac{3}{5}$$. Type the two numbers.`,titleHe:`8. חברו $$4\\dfrac{1}{5} + 2\\dfrac{3}{5}$$. כתבו את שני המספרים.`,textParts:[`$$4\\dfrac{1}{5} + 2\\dfrac{3}{5} = $$ `,` wholes and `,` fifths`],textPartsHe:[`$$4\\dfrac{1}{5} + 2\\dfrac{3}{5} = $$ `,` שלמים ועוד `,` חמישיות`],blanks:{1:{correct:`6`},2:{correct:`4`}},expEn:`Wholes: $$4 + 2 = 6$$. Fractions: $$\\dfrac{1}{5} + \\dfrac{3}{5} = \\dfrac{4}{5}$$. So $$6\\dfrac{4}{5}$$.`,expFr:`Les entiers : $$4 + 2 = 6$$. Les fractions : $$\\dfrac{1}{5} + \\dfrac{3}{5} = \\dfrac{4}{5}$$. Donc $$6\\dfrac{4}{5}$$.`,expHe:`השלמים: $$4 + 2 = 6$$. השברים: $$\\dfrac{1}{5} + \\dfrac{3}{5} = \\dfrac{4}{5}$$. ולכן $$6\\dfrac{4}{5}$$.`},{id:`a9_new_whole`,type:`mcq`,title:`9. $$2\\dfrac{5}{6} + 1\\dfrac{1}{3} = $$ ?`,titleHe:`9. $$2\\dfrac{5}{6} + 1\\dfrac{1}{3} = $$ ?`,options:[{val:`A`,text:`A. $$3\\dfrac{6}{9}$$`},{val:`B`,text:`B. $$4\\dfrac{1}{6}$$`},{val:`C`,text:`C. $$3\\dfrac{7}{6}$$`},{val:`D`,text:`D. $$3\\dfrac{1}{6}$$`}],correct:`B`,expEn:`$$2 + 1 = 3$$. $$\\dfrac{1}{3} = \\dfrac{2}{6}$$, and $$\\dfrac{5}{6} + \\dfrac{2}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$$: a new whole. $$3 + 1\\dfrac{1}{6} = 4\\dfrac{1}{6}$$. A adds the bottoms; C is not finished; D loses the new whole.`,expFr:`$$2 + 1 = 3$$. $$\\dfrac{1}{3} = \\dfrac{2}{6}$$, et $$\\dfrac{5}{6} + \\dfrac{2}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$$ : un nouvel entier. $$3 + 1\\dfrac{1}{6} = 4\\dfrac{1}{6}$$. A additionne les bas ; C n’est pas terminée ; D perd le nouvel entier.`,expHe:`$$2 + 1 = 3$$. $$\\dfrac{1}{3} = \\dfrac{2}{6}$$, ו-$$\\dfrac{5}{6} + \\dfrac{2}{6} = \\dfrac{7}{6} = 1\\dfrac{1}{6}$$: שלם חדש. $$3 + 1\\dfrac{1}{6} = 4\\dfrac{1}{6}$$. A מחבר את המכנים; C לא גמור; D מאבד את השלם החדש.`},{id:`a10_correct`,type:`mcq`,title:`10. Mr Bowen says $$1\\dfrac{2}{3} + 1\\dfrac{2}{3} = 2\\dfrac{4}{6}$$. Is he correct?`,titleHe:`10. מר בואן אומר $$1\\dfrac{2}{3} + 1\\dfrac{2}{3} = 2\\dfrac{4}{6}$$. האם הוא צודק?`,options:[{val:`A`,text:`A. Yes, because $$1 + 1 = 2$$ and $$2 + 2 = 4$$.`,textHe:`A. כן, כי $$1 + 1 = 2$$ ו-$$2 + 2 = 4$$.`},{val:`B`,text:`B. No, because $$\\dfrac{2}{3} + \\dfrac{2}{3} = 1\\dfrac{1}{3}$$, so it is $$3\\dfrac{1}{3}$$.`,textHe:`B. לא, כי $$\\dfrac{2}{3} + \\dfrac{2}{3} = 1\\dfrac{1}{3}$$, אז זה $$3\\dfrac{1}{3}$$.`},{val:`C`,text:`C. No, because it is $$2\\dfrac{4}{9}$$.`,textHe:`C. לא, כי זה $$2\\dfrac{4}{9}$$.`},{val:`D`,text:`D. No, because it is $$2\\dfrac{2}{3}$$.`,textHe:`D. לא, כי זה $$2\\dfrac{2}{3}$$.`}],correct:`B`,expEn:`He added the bottoms. $$\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$$, and $$2 + 1\\dfrac{1}{3} = 3\\dfrac{1}{3}$$. C multiplies the bottoms; D drops a third.`,expFr:`Il a additionné les bas. $$\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$$, et $$2 + 1\\dfrac{1}{3} = 3\\dfrac{1}{3}$$. C multiplie les bas ; D perd un tiers.`,expHe:`הוא חיבר את המכנים. $$\\dfrac{2}{3} + \\dfrac{2}{3} = \\dfrac{4}{3} = 1\\dfrac{1}{3}$$, ו-$$2 + 1\\dfrac{1}{3} = 3\\dfrac{1}{3}$$. C כופל את המכנים; D מאבד שליש.`}]},S={same:{title:`Same Denominator`,titleFr:`Même dénominateur`,titleHe:`אותו מכנה`,mode:`same`,levels:{1:{en:`Add the tops`,fr:`Additionne les hauts`,he:`מחברים את המונים`},2:{en:`Then the simplest form`,fr:`Puis la forme la plus simple`,he:`ואז מצמצמים`},3:{en:`On your own: more than 1`,fr:`À toi : plus de 1`,he:`לבד: יותר מ-1`}},items:[{id:`s1`,level:1,a:[2,9],b:[5,9]},{id:`s2`,level:1,a:[3,7],b:[1,7]},{id:`s4`,level:2,a:[1,10],b:[3,10]},{id:`s6`,level:2,a:[3,8],b:[3,8]},{id:`s8`,level:3,a:[9,10],b:[3,10]},{id:`s10`,level:3,a:[2,5],b:[4,5],c:[3,5]}]},match:{title:`Make Them Match`,titleFr:`Même taille`,titleHe:`מכנה משותף`,mode:`different`,levels:{1:{en:`One fraction changes`,fr:`Une fraction change`,he:`שבר אחד משתנה`},2:{en:`Both fractions change`,fr:`Les deux fractions changent`,he:`שני השברים משתנים`},3:{en:`On your own`,fr:`À toi de jouer`,he:`לבד`}},items:[{id:`m1`,level:1,a:[1,5],b:[7,10]},{id:`m2`,level:1,a:[2,3],b:[1,9],context:`Mr Bowen paints $\\dfrac{2}{3}$ of a wall before lunch and $\\dfrac{1}{9}$ after lunch.`,contextFr:`M. Bowen peint $\\dfrac{2}{3}$ d’un mur avant le déjeuner et $\\dfrac{1}{9}$ après le déjeuner.`,contextHe:`מר בואן צובע $\\dfrac{2}{3}$ מקיר לפני הצהריים ו-$\\dfrac{1}{9}$ אחרי הצהריים.`},{id:`m4`,level:1,a:[1,4],b:[5,12]},{id:`m5`,level:2,a:[1,3],b:[1,5]},{id:`m7`,level:2,a:[1,6],b:[3,8]},{id:`m8`,level:2,a:[1,6],b:[4,9],context:`Mr Bowen’s cat eats $\\dfrac{1}{6}$ of a bag of food on Monday and $\\dfrac{4}{9}$ on Tuesday.`,contextFr:`Le chat de M. Bowen mange $\\dfrac{1}{6}$ d’un sac de croquettes lundi et $\\dfrac{4}{9}$ mardi.`,contextHe:`החתול של מר בואן אוכל $\\dfrac{1}{6}$ משקית אוכל ביום שני ו-$\\dfrac{4}{9}$ ביום שלישי.`},{id:`m9`,level:3,a:[3,4],b:[2,3]},{id:`m11`,level:3,a:[3,4],b:[5,12]},{id:`m12`,level:3,a:[5,8],b:[5,6],context:`Mr Bowen pours $\\dfrac{5}{8}$ of a litre of juice and $\\dfrac{5}{6}$ of a litre of water into a jug.`,contextFr:`M. Bowen verse $\\dfrac{5}{8}$ de litre de jus et $\\dfrac{5}{6}$ de litre d’eau dans une carafe.`,contextHe:`מר בואן מוזג $\\dfrac{5}{8}$ ליטר מיץ ו-$\\dfrac{5}{6}$ ליטר מים לתוך קנקן.`}]}},C={meta:{id:`U07_2`,title:`Adding Fractions`,desc:`Adding fractions with the same denominator; the simplest form and mixed numbers; a common denominator (the LCM) for different denominators; adding mixed numbers: wholes, fractions, a new whole.`,track:`Y7_MATH`,icon:`Plus`,vietnamese:!1,hebrew:!0,audio:!1,classroom:[{course:`y7-math`,slug:`U07_2a`,title:`Maths 7.2 Part 1 · Adding Fractions`},{course:`y7-math`,slug:`U07_2`,title:`Maths 7.2 Part 2 · Adding Mixed Numbers`}]},realWords:[{word:`Denominator`,fr:`Dénominateur`,he:`מכנה`,def:`The bottom number of a fraction: how many equal pieces make one whole.`,frDef:`Le nombre du bas d’une fraction : combien de parts égales font un entier.`,heDef:`המספר התחתון בשבר: כמה חלקים שווים יוצרים שלם אחד.`,sent:`In 3/8 the denominator is 8.`,frSent:`Dans 3/8, le dénominateur est 8.`,heSent:`ב-3/8 המכנה הוא 8.`,isReal:!0},{word:`Simplest form`,fr:`Forme la plus simple`,he:`הצורה המצומצמת`,def:`The same fraction with the smallest numbers: divide the top and the bottom by their HCF.`,frDef:`La même fraction avec les plus petits nombres : divise le haut et le bas par leur PGCD.`,heDef:`אותו שבר עם המספרים הקטנים ביותר: מחלקים את המונה ואת המכנה בממג"ב שלהם.`,sent:`8/12 in its simplest form is 2/3.`,frSent:`8/12 sous sa forme la plus simple, c’est 2/3.`,heSent:`8/12 בצורה המצומצמת הוא 2/3.`,isReal:!0},{word:`Common denominator`,fr:`Dénominateur commun`,he:`מכנה משותף`,def:`The same bottom number for two fractions, found in both times tables.`,frDef:`Le même nombre en bas pour deux fractions, trouvé dans les deux tables.`,heDef:`אותו מכנה לשני שברים, שנמצא בשני לוחות הכפל.`,sent:`12 is a common denominator for 1/3 and 1/4.`,frSent:`12 est un dénominateur commun pour 1/3 et 1/4.`,heSent:`12 הוא מכנה משותף ל-1/3 ול-1/4.`,isReal:!0},{word:`Lowest common multiple`,fr:`Plus petit commun multiple`,he:`כפולה משותפת קטנה ביותר`,def:`The smallest number in both times tables (LCM).`,frDef:`Le plus petit nombre qui est dans les deux tables (PPCM).`,heDef:`המספר הקטן ביותר שנמצא בשני לוחות הכפל (כמק"ב).`,sent:`The LCM of 4 and 6 is 12, not 24.`,frSent:`Le PPCM de 4 et 6 est 12, pas 24.`,heSent:`הכמק"ב של 4 ו-6 הוא 12, לא 24.`,isReal:!0},{word:`Mixed number`,fr:`Nombre mixte`,he:`מספר מעורב`,def:`A whole number and a fraction together, like 3 1/2.`,frDef:`Un nombre entier et une fraction ensemble, comme 3 1/2.`,heDef:`מספר שלם ושבר יחד, כמו 3 1/2.`,sent:`7/2 as a mixed number is 3 1/2.`,frSent:`7/2 en nombre mixte, c’est 3 1/2.`,heSent:`7/2 כמספר מעורב הוא 3 1/2.`,isReal:!0},{word:`Estimate`,fr:`Estimer`,he:`אומדן`,def:`A quick answer, found first: add the whole numbers.`,frDef:`Une réponse rapide, trouvée d’abord : additionne les nombres entiers.`,heDef:`תשובה מהירה, שמוצאים קודם: מחברים את המספרים השלמים.`,sent:`Estimate first: 2 1/5 + 3 2/5 is between 5 and 6.`,frSent:`Estime d’abord : 2 1/5 + 3 2/5 est entre 5 et 6.`,heSent:`קודם אומדן: 2 1/5 + 3 2/5 הוא בין 5 ל-6.`,isReal:!0}],notes:p,notes2:b,assessment:x,same:S.same,match:S.match};export{C as U07_2_DATA};